mapper.sql:

WHERE r.tenant_id=#{tenant}
AND r.job_type=#{q.filters.jobType}
AND (
  (r.job_type='PAYMENT_CALLBACK' AND EXISTS (
    SELECT 1 FROM tc_payment_callback c WHERE c.tenant_id=r.tenant_id AND c.callback_no=r.business_key
      AND c.business_no=#{q.filters.callbackNo}
        c.callback_no=#{q.filters.callbackNo}))
  OR (r.job_type='REFUND_CALLBACK' AND EXISTS (
    SELECT 1 FROM tc_refund_callback c WHERE c.tenant_id=r.tenant_id AND c.callback_no=r.business_key
      AND c.business_no=#{q.filters.callbackNo}
        c.callback_no=#{q.filters.callbackNo}))
)
AND r.status=#{q.filters.status}
AND (r.status='RUNNING' AND r.lease_until <= #{at})=#{q.filters.leaseExpired}
AND r.created_at >= #{q.createdFrom} AND r.created_at < #{q.createdTo}

mapper.select:
SELECT  
AND r.id > #{q.after}
ORDER BY r.id ASC LIMIT #{q.fetchLimit}
